import { useAuth } from "@/_core/hooks/useAuth";
import { AIChatBox, Message } from "@/components/AIChatBox";
import DashboardLayout from "@/components/DashboardLayout";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { trpc } from "@/lib/trpc";
import { Area, AreaChart, Bar, BarChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts";
import { Streamdown } from "streamdown";
import { Archive, ArrowLeft, ArrowRight, BarChart3, BookOpenText, BrainCircuit, CalendarDays, Check, CheckCircle2, ChevronLeft, ChevronRight, ClipboardList, Clock3, Copy, Download, FileText, Filter, Layers3, Lightbulb, ListPlus, Loader2, MessageSquareText, MoreHorizontal, NotebookPen, PenLine, Plus, RotateCcw, Search, Sparkles, Trash2, Upload, WandSparkles, X } from "lucide-react";
import React, { ChangeEvent, useEffect, useMemo, useRef, useState } from "react";
import { useLocation } from "wouter";

type StudyDay = { day: number; focus: string; duration: string; complete: boolean };
type QuizQuestion = { id: string; prompt: string; options: string[]; answer: number; explanation: string };

const pageMeta: Record<string, { eyebrow: string; title: string; copy: string }> = {
  dashboard: { eyebrow: "Your learning command center", title: "Good morning. Let’s make progress feel inevitable.", copy: "A calm view of what matters today, with enough signal to make the next decision easy." },
  assistant: { eyebrow: "Learnova AI", title: "Your on-demand study partner", copy: "Ask for an explanation, create a revision path, or turn material into active recall." },
  planner: { eyebrow: "Study planner", title: "Shape your next seven days", copy: "Build a practical plan around your subject, exam date, and available energy." },
  tasks: { eyebrow: "Task manager", title: "Protect your attention", copy: "Capture coursework, surface priorities, and turn open loops into a clear plan." },
  notes: { eyebrow: "Notes workspace", title: "Make your knowledge findable", copy: "Keep thoughts, lecture notes, and revision material structured around the way you learn." },
  documents: { eyebrow: "Document workspace", title: "Bring your material into focus", copy: "Upload a study document, extract readable text, and ask for the parts that matter most." },
  quiz: { eyebrow: "Quiz studio", title: "Practice retrieval, not rereading", copy: "Generate a focused practice set and see exactly what needs another pass." },
  flashcards: { eyebrow: "Flashcards", title: "Create memory cues that stick", copy: "Generate compact cards, flip through them, and mark what is ready or needs review." },
  summarize: { eyebrow: "AI summarizer", title: "Find the signal in the noise", copy: "Turn rough notes or study material into a useful summary with key points and questions." },
  calendar: { eyebrow: "Calendar", title: "Make your time visible", copy: "Hold deadlines, exams, tasks, and focused sessions in one simple study calendar." },
  analytics: { eyebrow: "Learning analytics", title: "See the habits behind the outcome", copy: "Follow study time, completion, assessment trends, and your current learning rhythm." },
  settings: { eyebrow: "Personal settings", title: "Tune Learnova to your style", copy: "Manage your study preferences and shape how your workspace feels." },
};

function timeGreeting(now: Date) {
  const hour = now.getHours();
  if (hour < 12) return "Good morning";
  if (hour < 17) return "Good afternoon";
  return "Good evening";
}

export default function Workspace() {
  const [location] = useLocation();
  const section = location === "/dashboard" ? "dashboard" : location.split("/")[2] || "dashboard";
  const meta = pageMeta[section] || pageMeta.dashboard;
  const [now, setNow] = useState(() => new Date());
  useEffect(() => { const interval = window.setInterval(() => setNow(new Date()), 60_000); return () => window.clearInterval(interval); }, []);
  const heading = section === "dashboard" ? `${timeGreeting(now)}. Let’s make progress feel inevitable.` : meta.title;
  return <DashboardLayout><section className="mb-8"><p className="nova-eyebrow nova-eyebrow-app">{meta.eyebrow}</p><h1 className="mt-3 max-w-3xl text-3xl font-semibold tracking-[-.04em] sm:text-4xl">{heading}</h1><p className="mt-3 max-w-2xl text-sm leading-6 text-muted-foreground sm:text-base">{meta.copy}</p></section>{section === "dashboard" && <DashboardPage />}{section === "tasks" && <TasksPage />}{section === "notes" && <NotesWorkspace />}{section === "assistant" && <AssistantWorkspace />}{section === "documents" && <DocumentsPage />}{section === "planner" && <PlannerWorkspace />}{section === "quiz" && <QuizPage />}{section === "flashcards" && <FlashcardsWorkspace />}{section === "summarize" && <SummarizePage />}{section === "calendar" && <CalendarWorkspace />}{section === "analytics" && <AnalyticsPage />}{section === "settings" && <SettingsWorkspace />}</DashboardLayout>;
}

function DashboardPage() {
  const { user } = useAuth();
  const { data, isLoading } = trpc.dashboard.overview.useQuery();
  const [, navigate] = useLocation();
  if (isLoading) return <LoadingCards />;
  const metrics = data?.metrics || { studyHours: 0, completedTasks: 0, totalTasks: 0, quizScore: 0, streak: 0 };
  const metricCards = [["Study hours", `${metrics.studyHours}h`, "this week", Clock3, "cyan"], ["Tasks complete", `${metrics.completedTasks}/${metrics.totalTasks}`, "this week", CheckCircle2, "violet"], ["Quiz score", `${metrics.quizScore}%`, "average", BrainCircuit, "blue"], ["Current streak", `${metrics.streak} days`, "keep it alive", Sparkles, "rose"]] as const;
  return <div className="space-y-6"><div className="nova-welcome"><div><p className="text-sm text-orange-600">Welcome back, {user?.name?.split(" ")[0] || "learner"}.</p><h2>One focused decision at a time.</h2><p>Today is a good day to deepen the work that is already underway.</p></div><button onClick={() => navigate("/app/assistant")} className="nova-button"><Sparkles size={16} /> Ask Learnova</button></div><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{metricCards.map(([label, value, note, Icon, color]) => <article className="nova-stat-card" key={label}><span className={`nova-stat-icon nova-stat-${color}`}><Icon size={19} /></span><div><p>{label}</p><strong>{value}</strong><small>{note}</small></div></article>)}</div><div className="grid gap-6 xl:grid-cols-[1.3fr_.7fr]"><Panel title="Study rhythm" action="Analytics" onAction={() => navigate("/app/analytics")}><div className="h-[255px]">{data?.progress?.some((item) => item.minutes) ? <ResponsiveContainer width="100%" height="100%"><AreaChart data={data.progress}><defs><linearGradient id="studyGradient" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stopColor="#f4a340" stopOpacity={.4} /><stop offset="100%" stopColor="#ef7d31" stopOpacity={0} /></linearGradient></defs><XAxis dataKey="label" axisLine={false} tickLine={false} tick={{ fill: "#9a7357", fontSize: 12 }} /><Tooltip contentStyle={{ borderRadius: 16, background: "#fff8ec", border: "1px solid rgba(255,255,255,.1)" }} /><Area type="monotone" dataKey="minutes" stroke="#e86d2d" strokeWidth={2.5} fill="url(#studyGradient)" /></AreaChart></ResponsiveContainer> : <Empty text="Log a study session from Calendar to begin your progress view." icon={BarChart3} />}</div></Panel><div className="space-y-6"><Panel title="AI recommendation"><div className="nova-recommendation"><Lightbulb size={19} /><p>{data?.recommendation || "Capture one small goal and turn it into a focused 30-minute session."}</p><button onClick={() => navigate("/app/planner")}><ArrowRight size={16} /></button></div></Panel><Panel title="Quick actions"><div className="grid grid-cols-2 gap-2">{[["Ask AI", "/app/assistant", MessageSquareText], ["Add task", "/app/tasks", Plus], ["Create note", "/app/notes", PenLine], ["Upload PDF", "/app/documents", Upload], ["Generate quiz", "/app/quiz", GraduationCapIcon], ["Plan study", "/app/planner", ClipboardList]].map(([label, path, Icon]) => <button key={label as string} onClick={() => navigate(path as string)} className="nova-quick-action"><Icon size={16} /><span>{label as string}</span></button>)}</div></Panel></div></div><div className="grid gap-6 xl:grid-cols-[1.1fr_.9fr]"><Panel title="Today’s tasks" action="View all" onAction={() => navigate("/app/tasks")}>{data?.tasks?.length ? <div className="space-y-2">{data.tasks.map((task) => <div className="nova-list-row" key={task.id}><span className={`nova-priority-dot nova-priority-${task.priority}`} /><div className="min-w-0 flex-1"><p className="truncate font-medium">{task.title}</p><small>{task.category} {task.deadline ? `· Due ${formatDate(task.deadline)}` : ""}</small></div><span className="nova-status">{task.priority}</span></div>)}</div> : <Empty text="Your task list is clear. Capture the next coursework action." icon={CheckSquareIcon} />}</Panel><Panel title="Recent notes" action="Open notes" onAction={() => navigate("/app/notes")}>{data?.notes?.length ? <div className="space-y-2">{data.notes.map((note) => <button className="nova-note-row" key={note.id} onClick={() => navigate("/app/notes")}><span><BookOpenText size={17} /></span><div className="min-w-0 text-left"><p className="truncate font-medium">{note.title}</p><small>{note.subject} · Updated {formatDate(note.updatedAt)}</small></div><ArrowRight size={15} /></button>)}</div> : <Empty text="Save your first note to make revision material easy to revisit." icon={NotebookIcon} />}</Panel></div></div>;
}

function TasksPage() {
  const [filter, setFilter] = useState<"all" | "today" | "upcoming" | "completed">("all"); const [showForm, setShowForm] = useState(false); const [editing, setEditing] = useState<any>(null); const utils = trpc.useUtils();
  const { data: taskData, isLoading } = trpc.productivity.tasks.list.useQuery({ filter }); const create = trpc.productivity.tasks.create.useMutation({ onSuccess: () => { utils.productivity.tasks.list.invalidate(); setShowForm(false); } }); const update = trpc.productivity.tasks.update.useMutation({ onSuccess: () => { utils.productivity.tasks.list.invalidate(); setEditing(null); } }); const remove = trpc.productivity.tasks.remove.useMutation({ onSuccess: () => utils.productivity.tasks.list.invalidate() }); const toggle = trpc.productivity.tasks.toggle.useMutation({ onSuccess: () => utils.productivity.tasks.list.invalidate() });
  const submit = (event: React.FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = new FormData(event.currentTarget); const payload = { title: String(form.get("title")), description: String(form.get("description") || ""), category: String(form.get("category") || "General"), priority: String(form.get("priority")) as "low" | "medium" | "high", status: String(form.get("status")) as "pending" | "in_progress" | "completed", deadline: form.get("deadline") ? new Date(String(form.get("deadline"))) : null }; editing ? update.mutate({ ...payload, id: editing.id }) : create.mutate(payload); };
  return <div className="space-y-6"><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-center"><div className="nova-filter-tabs">{(["all", "today", "upcoming", "completed"] as const).map((item) => <button className={filter === item ? "is-active" : ""} key={item} onClick={() => setFilter(item)}>{item}</button>)}</div><button className="nova-button" onClick={() => { setEditing(null); setShowForm(true); }}><Plus size={16} /> New task</button></div>{(showForm || editing) && <form onSubmit={submit} className="nova-form-card grid gap-4 md:grid-cols-2"><div className="md:col-span-2 flex justify-between"><strong>{editing ? "Edit task" : "Capture a task"}</strong><button type="button" onClick={() => { setShowForm(false); setEditing(null); }}><X size={17} /></button></div><Input required name="title" placeholder="What needs your attention?" defaultValue={editing?.title} className="nova-input" /><Input name="category" placeholder="Category (e.g. Coursework)" defaultValue={editing?.category || "General"} className="nova-input" /><Textarea name="description" placeholder="A little context helps." defaultValue={editing?.description || ""} className="nova-input min-h-24 md:col-span-2" /><select name="priority" defaultValue={editing?.priority || "medium"} className="nova-input"><option value="low">Low priority</option><option value="medium">Medium priority</option><option value="high">High priority</option></select><select name="status" defaultValue={editing?.status || "pending"} className="nova-input"><option value="pending">Pending</option><option value="in_progress">In progress</option><option value="completed">Completed</option></select><Input name="deadline" type="date" defaultValue={editing?.deadline ? dateInput(editing.deadline) : ""} className="nova-input" /><div className="flex justify-end"><button className="nova-button" type="submit" disabled={create.isPending || update.isPending}>{create.isPending || update.isPending ? <Loader2 className="animate-spin" size={16} /> : <Check size={16} />}{editing ? "Save changes" : "Add task"}</button></div></form>}<Panel title="Your tasks" action={`${taskData?.length || 0} items`}>{isLoading ? <LoadingRows /> : taskData?.length ? <div className="divide-y divide-border/60">{taskData.map((task) => <div className="nova-task-row" key={task.id}><button onClick={() => toggle.mutate({ id: task.id, complete: task.status !== "completed" })} className={`nova-check ${task.status === "completed" ? "is-done" : ""}`}>{task.status === "completed" && <Check size={13} />}</button><div className="min-w-0 flex-1"><p className={task.status === "completed" ? "line-through opacity-60" : ""}>{task.title}</p><small>{task.category} · <span className={`nova-text-${task.priority}`}>{task.priority} priority</span>{task.deadline ? ` · Due ${formatDate(task.deadline)}` : ""}</small></div><span className="hidden rounded-lg bg-muted px-2.5 py-1 text-xs capitalize sm:block">{task.status.replace("_", " ")}</span><div className="flex gap-1"><button onClick={() => { setEditing(task); setShowForm(false); }} className="nova-icon-button"><PenLine size={15} /></button><button onClick={() => { if (confirm("Remove this task?")) remove.mutate({ id: task.id }); }} className="nova-icon-button hover:text-rose-400"><Trash2 size={15} /></button></div></div>)}</div> : <Empty text="No tasks in this view. Add the next meaningful action to regain momentum." icon={ClipboardList} />}</Panel></div>;
}

function NotesPage() {
  const [query, setQuery] = useState(""); const [showForm, setShowForm] = useState(false); const [editing, setEditing] = useState<any>(null); const utils = trpc.useUtils(); const { data: noteData, isLoading } = trpc.productivity.notes.list.useQuery({ query }); const create = trpc.productivity.notes.create.useMutation({ onSuccess: () => { utils.productivity.notes.list.invalidate(); setShowForm(false); } }); const update = trpc.productivity.notes.update.useMutation({ onSuccess: () => { utils.productivity.notes.list.invalidate(); setEditing(null); } }); const remove = trpc.productivity.notes.remove.useMutation({ onSuccess: () => utils.productivity.notes.list.invalidate() });
  const submit = (event: React.FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = new FormData(event.currentTarget); const payload = { title: String(form.get("title")), subject: String(form.get("subject") || "General"), content: String(form.get("content")), tags: String(form.get("tags") || "") }; editing ? update.mutate({ ...payload, id: editing.id }) : create.mutate(payload); };
  return <div className="space-y-6"><div className="flex flex-col justify-between gap-3 sm:flex-row"><label className="nova-search"><Search size={16} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search titles" /></label><button className="nova-button" onClick={() => { setEditing(null); setShowForm(true); }}><Plus size={16} /> New note</button></div>{(showForm || editing) && <form onSubmit={submit} className="nova-form-card grid gap-4 md:grid-cols-2"><div className="md:col-span-2 flex justify-between"><strong>{editing ? "Edit note" : "Capture an idea"}</strong><button type="button" onClick={() => { setShowForm(false); setEditing(null); }}><X size={17} /></button></div><Input required name="title" placeholder="A useful, clear title" defaultValue={editing?.title} className="nova-input" /><Input name="subject" placeholder="Subject" defaultValue={editing?.subject || "General"} className="nova-input" /><Input name="tags" placeholder="Tags separated by commas" defaultValue={editing?.tags || ""} className="nova-input md:col-span-2" /><Textarea required name="content" placeholder="Write the key idea, explanation, or question…" defaultValue={editing?.content || ""} className="nova-input min-h-48 md:col-span-2" /><div className="flex justify-end md:col-span-2"><button className="nova-button" type="submit"><Check size={16} />{editing ? "Save note" : "Create note"}</button></div></form>}<div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{isLoading ? <LoadingCards count={6} /> : noteData?.length ? noteData.map((note) => <article className="nova-note-card" key={note.id}><div className="flex justify-between gap-3"><span className="nova-subject-pill">{note.subject}</span><div className="flex"><button onClick={() => { setEditing(note); setShowForm(false); }} className="nova-icon-button"><PenLine size={15} /></button><button onClick={() => { if (confirm("Delete this note?")) remove.mutate({ id: note.id }); }} className="nova-icon-button hover:text-rose-400"><Trash2 size={15} /></button></div></div><h3>{note.title}</h3><p>{note.content}</p><div><small>{note.tags || "No tags"}</small><small>{formatDate(note.updatedAt)}</small></div></article>) : <div className="md:col-span-2 xl:col-span-3"><Empty text="This is a quiet canvas. Create a note from a lecture, a reading, or a question you want to revisit." icon={BookOpenText} /></div>}</div></div>;
}

function AssistantPage() {
  const utils = trpc.useUtils(); const { data, isLoading } = trpc.learning.chat.list.useQuery({ conversationId: "primary" }); const send = trpc.learning.chat.send.useMutation({ onSuccess: () => utils.learning.chat.list.invalidate() }); const clear = trpc.learning.chat.clear.useMutation({ onSuccess: () => utils.learning.chat.list.invalidate() }); const messages: Message[] = (data || []).map((message) => ({ role: message.role, content: message.message }));
  return <div className="grid gap-6 xl:grid-cols-[.28fr_.72fr]"><Panel title="Prompt library"><div className="space-y-2">{["Explain normalization simply.", "Create a study plan for my exam.", "Quiz me on Python.", "Turn this topic into flashcards."].map((prompt) => <button key={prompt} onClick={() => send.mutate({ message: prompt, conversationId: "primary" })} className="nova-prompt"><Sparkles size={15} />{prompt}</button>)}</div><div className="mt-6 border-t border-border pt-5"><p className="text-xs leading-5 text-muted-foreground">Learnova keeps your conversation in your private workspace and uses a safe local study-coach response whenever an external model is unavailable.</p><button onClick={() => { if (confirm("Clear this private conversation?")) clear.mutate({ conversationId: "primary" }); }} className="mt-4 flex items-center gap-2 text-sm text-muted-foreground hover:text-rose-400"><Trash2 size={15} /> Clear chat</button></div></Panel><div className="nova-chat-shell"><div className="nova-chat-top"><span className="nova-mark h-8 w-8"><Sparkles size={14} /></span><div><p className="text-sm font-medium">Learnova study coach</p><p className="text-xs text-orange-600">Ready for your next question</p></div><label className="ml-auto nova-attach"><Upload size={15} /> <span>Attach context</span><input type="file" onChange={() => undefined} /></label></div><AIChatBox messages={messages} onSendMessage={(message) => send.mutate({ message, conversationId: "primary" })} isLoading={isLoading || send.isPending} height="570px" className="border-0 bg-transparent shadow-none" emptyStateMessage="Start with a topic, a confusing concept, or a study goal." suggestedPrompts={["Explain this simply", "Create a study plan", "Quiz me on this topic"]} /></div></div>;
}

function DocumentsPage() {
  const utils = trpc.useUtils(); const fileRef = useRef<HTMLInputElement>(null); const [selected, setSelected] = useState<any>(null); const [question, setQuestion] = useState(""); const { data, isLoading } = trpc.learning.documents.list.useQuery(); const upload = trpc.learning.documents.upload.useMutation({ onSuccess: (result, variables) => { setSelected({ id: Number(result.id), filename: variables.filename, mimeType: variables.mimeType, fileSize: Math.floor(variables.base64.length * 0.75), extractedText: result.extractedText, createdAt: new Date() }); utils.learning.documents.list.invalidate(); } }); const remove = trpc.learning.documents.remove.useMutation({ onSuccess: () => { utils.learning.documents.list.invalidate(); setSelected(null); } }); const ask = trpc.learning.documents.ask.useMutation();
  const chooseFile = (event: ChangeEvent<HTMLInputElement>) => { const file = event.target.files?.[0]; if (!file) return; const reader = new FileReader(); reader.onload = () => { const result = String(reader.result); upload.mutate({ filename: file.name, mimeType: file.type, base64: result.split(",")[1] || "" }); }; reader.readAsDataURL(file); };
  return <div className="grid gap-6 xl:grid-cols-[.85fr_1.15fr]"><div className="space-y-5"><button className="nova-upload-zone w-full" onClick={() => fileRef.current?.click()} disabled={upload.isPending}>{upload.isPending ? <Loader2 className="animate-spin" size={24} /> : <Upload size={24} />}<strong>{upload.isPending ? "Processing your material…" : "Add study material"}</strong><p>PDF, DOCX, or TXT · up to 5 MB</p><input ref={fileRef} type="file" accept=".pdf,.docx,.txt,application/pdf,text/plain,application/vnd.openxmlformats-officedocument.wordprocessingml.document" onChange={chooseFile} /></button><Panel title="Your library" action={`${data?.length || 0} files`}>{isLoading ? <LoadingRows /> : data?.length ? <div className="space-y-2">{data.map((document) => <button onClick={() => setSelected(document)} key={document.id} className={`nova-document-row ${selected?.id === document.id ? "is-selected" : ""}`}><span><FileText size={18} /></span><div className="min-w-0 flex-1 text-left"><p className="truncate">{document.filename}</p><small>{Math.round(document.fileSize / 1024)} KB · {formatDate(document.createdAt)}</small></div><ArrowRight size={15} /></button>)}</div> : <Empty text="Upload your first lecture file, reading, or revision sheet." icon={FileText} />}</Panel></div><Panel title={selected ? selected.filename : "Document intelligence"}>{selected ? <div className="space-y-5"><div className="rounded-2xl border border-border bg-muted/35 p-4"><p className="text-xs uppercase tracking-[.13em] text-muted-foreground">Extracted text</p><p className="mt-3 max-h-48 overflow-auto whitespace-pre-wrap text-sm leading-6 text-muted-foreground">{selected.extractedText.slice(0, 1600)}{selected.extractedText.length > 1600 ? "…" : ""}</p></div><div className="grid grid-cols-2 gap-2 sm:grid-cols-4">{["Summarize this", "Key topics", "Generate questions", "Explain simply"].map((label) => <button key={label} onClick={() => { setQuestion(label); ask.mutate({ documentId: selected.id, question: label }); }} className="nova-quick-action"><WandSparkles size={15} /><span>{label}</span></button>)}</div><div className="rounded-2xl border border-orange-300/25 bg-amber-100/45 p-5"><p className="text-sm font-medium">Ask about this material</p><div className="mt-3 flex gap-2"><Input value={question} onChange={(event) => setQuestion(event.target.value)} placeholder="What should I focus on?" className="nova-input" /><button onClick={() => question && ask.mutate({ documentId: selected.id, question })} className="nova-button" disabled={ask.isPending}>{ask.isPending ? <Loader2 className="animate-spin" size={16} /> : <ArrowRight size={16} />}</button></div>{ask.data?.response && <div className="prose prose-sm mt-4 max-w-none dark:prose-invert"><Streamdown>{ask.data.response}</Streamdown></div>}</div><button onClick={() => { if (confirm("Remove this document from your private workspace?")) remove.mutate({ id: selected.id }); }} className="flex items-center gap-2 text-sm text-rose-400"><Trash2 size={15} /> Remove document</button></div> : <Empty text="Choose a document to view its extracted text and ask focused study questions." icon={BrainCircuit} />}</Panel></div>;
}

function PlannerPage() {
  const utils = trpc.useUtils(); const { data, isLoading } = trpc.learning.planner.list.useQuery(); const generate = trpc.learning.planner.generate.useMutation({ onSuccess: () => utils.learning.planner.list.invalidate() }); const update = trpc.learning.planner.update.useMutation({ onSuccess: () => utils.learning.planner.list.invalidate() }); const remove = trpc.learning.planner.remove.useMutation({ onSuccess: () => utils.learning.planner.list.invalidate() }); const [showForm, setShowForm] = useState(true);
  const submit = (event: React.FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = new FormData(event.currentTarget); generate.mutate({ subject: String(form.get("subject")), topics: String(form.get("topics")), examDate: form.get("examDate") ? new Date(String(form.get("examDate"))) : null, availableHours: Number(form.get("hours")), preferredTime: String(form.get("time")), knowledgeLevel: String(form.get("level")) }); };
  const toggleDay = (plan: any, index: number) => { const days = ((plan.planData || []) as StudyDay[]).map((day, dayIndex) => dayIndex === index ? { ...day, complete: !day.complete } : day); update.mutate({ id: plan.id, planData: days, progress: Math.round((days.filter((day) => day.complete).length / Math.max(days.length, 1)) * 100) }); };
  return <div className="space-y-6">{showForm && <form onSubmit={submit} className="nova-form-card grid gap-4 md:grid-cols-2"><div className="md:col-span-2 flex justify-between"><strong>Build a study plan</strong><button type="button" onClick={() => setShowForm(false)}><X size={17} /></button></div><Input required name="subject" placeholder="Subject (e.g. DBMS)" className="nova-input" /><Input name="examDate" type="date" className="nova-input" /><Textarea required name="topics" placeholder="Topics to cover, separated by commas or new lines" className="nova-input min-h-28 md:col-span-2" /><select name="hours" defaultValue="1" className="nova-input"><option value="1">1 hour daily</option><option value="2">2 hours daily</option><option value="3">3 hours daily</option></select><select name="time" defaultValue="Evening" className="nova-input"><option>Morning</option><option>Afternoon</option><option>Evening</option><option>Flexible</option></select><select name="level" defaultValue="Developing" className="nova-input"><option>New to this topic</option><option>Developing</option><option>Confident</option></select><div className="flex justify-end"><button className="nova-button" disabled={generate.isPending}>{generate.isPending ? <Loader2 className="animate-spin" size={16} /> : <WandSparkles size={16} />} Generate plan</button></div></form>}{!showForm && <button className="nova-button" onClick={() => setShowForm(true)}><Plus size={16} /> New study plan</button>}<div className="grid gap-5 xl:grid-cols-2">{isLoading ? <LoadingCards count={2} /> : data?.length ? data.map((plan) => { const days = (plan.planData || []) as StudyDay[]; return <article className="nova-plan-card" key={plan.id}><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="nova-subject-pill">{plan.subject}</p><h3>{plan.topics.split(/[,\n]/)[0]} and more</h3><p>{plan.examDate ? `Exam: ${formatDate(plan.examDate)}` : "No exam date set"} · {plan.availableHours}h daily</p></div><button onClick={() => { if (confirm("Delete this study plan?")) remove.mutate({ id: plan.id }); }} className="nova-icon-button hover:text-rose-400"><Trash2 size={15} /></button></div><div className="mt-5 h-1.5 overflow-hidden rounded-full bg-muted"><span className="block h-full rounded-full bg-gradient-to-r from-amber-300 to-orange-500" style={{ width: `${plan.progress}%` }} /></div><p className="mt-2 text-xs text-muted-foreground">{plan.progress}% complete</p><div className="mt-5 space-y-2">{days.map((day, index) => <button key={day.day} className="nova-plan-day" onClick={() => toggleDay(plan, index)}><span className={`nova-check ${day.complete ? "is-done" : ""}`}>{day.complete && <Check size={13} />}</span><span className="text-xs text-muted-foreground">Day {day.day}</span><span className={day.complete ? "line-through opacity-60" : ""}>{day.focus}</span><small>{day.duration}</small></button>)}</div></article>; }) : <div className="xl:col-span-2"><Empty text="Create a plan with your topics and availability. Learnova will turn it into a manageable week." icon={ClipboardList} /></div>}</div></div>;
}

function QuizPage() {
  const utils = trpc.useUtils(); const { data: history } = trpc.learning.quiz.list.useQuery(); const generate = trpc.learning.quiz.generate.useMutation(); const record = trpc.learning.quiz.record.useMutation({ onSuccess: () => utils.learning.quiz.list.invalidate() }); const [active, setActive] = useState<{ id: number; questions: QuizQuestion[]; topic: string } | null>(null); const [answers, setAnswers] = useState<Record<string, number>>({}); const [result, setResult] = useState<number | null>(null);
  const submit = (event: React.FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = new FormData(event.currentTarget); generate.mutate({ topic: String(form.get("topic")), difficulty: String(form.get("difficulty")) as "easy" | "medium" | "hard", questionType: String(form.get("type")) as "mcq" | "true_false", count: Number(form.get("count")) }, { onSuccess: (data) => { setActive({ id: data.id, questions: data.questions, topic: String(form.get("topic")) }); setAnswers({}); setResult(null); } }); };
  const grade = () => { if (!active) return; const score = Math.round((active.questions.filter((question) => answers[question.id] === question.answer).length / active.questions.length) * 100); setResult(score); record.mutate({ id: active.id, answers, score }); };
  return <div className="grid gap-6 xl:grid-cols-[.7fr_1.3fr]"><div className="space-y-6"><form onSubmit={submit} className="nova-form-card space-y-4"><strong>Create a practice set</strong><Input required name="topic" placeholder="What are you studying?" className="nova-input" /><select name="difficulty" className="nova-input"><option value="easy">Easy</option><option value="medium">Medium</option><option value="hard">Hard</option></select><div className="grid grid-cols-2 gap-3"><select name="count" className="nova-input"><option value="5">5 questions</option><option value="10">10 questions</option><option value="15">15 questions</option><option value="20">20 questions</option></select><select name="type" className="nova-input"><option value="mcq">MCQ</option><option value="true_false">True / False</option></select></div><button className="nova-button w-full" disabled={generate.isPending}>{generate.isPending ? <Loader2 className="animate-spin" size={16} /> : <WandSparkles size={16} />} Generate quiz</button></form><Panel title="Past attempts">{history?.length ? <div className="space-y-2">{history.slice(0, 5).map((quiz) => <div className="nova-list-row" key={quiz.id}><span className="nova-stat-icon nova-stat-violet"><BrainCircuit size={15} /></span><div className="min-w-0 flex-1"><p className="truncate">{quiz.topic}</p><small>{formatDate(quiz.createdAt)}</small></div><strong className="text-sm">{quiz.score === null ? "Draft" : `${quiz.score}%`}</strong></div>)}</div> : <Empty text="Your completed practice sets will show here." icon={GraduationCapIcon} />}</Panel></div><Panel title={active ? `${active.topic} practice` : "Ready for active recall"}>{active ? <div className="space-y-6">{active.questions.map((question, index) => <div key={question.id} className="nova-question"><div className="flex gap-3"><span>{String(index + 1).padStart(2, "0")}</span><p>{question.prompt}</p></div><div className="mt-4 grid gap-2">{question.options.map((option, optionIndex) => <button key={option} onClick={() => result === null && setAnswers((old) => ({ ...old, [question.id]: optionIndex }))} className={`nova-option ${answers[question.id] === optionIndex ? "is-selected" : ""} ${result !== null && optionIndex === question.answer ? "is-correct" : ""}`}>{option}</button>)}</div>{result !== null && <p className="mt-3 text-sm leading-6 text-muted-foreground"><strong className="text-foreground">Why:</strong> {question.explanation}</p>}</div>)}{result === null ? <button disabled={Object.keys(answers).length !== active.questions.length || record.isPending} onClick={grade} className="nova-button">Grade my answers <ArrowRight size={16} /></button> : <div className="nova-score"><span>{result}%</span><div><strong>{result >= 70 ? "Strong recall." : "Useful signal."}</strong><p>{result >= 70 ? "You can now push this topic with a few harder examples." : "Revisit the explanations and try another set when you are ready."}</p></div></div>}</div> : <Empty text="Choose a topic and let Learnova create a short, focused practice set." icon={BrainCircuit} />}</Panel></div>;
}

function FlashcardsPage() {
  const utils = trpc.useUtils(); const { data } = trpc.learning.flashcards.list.useQuery({}); const generate = trpc.learning.flashcards.generate.useMutation({ onSuccess: () => utils.learning.flashcards.list.invalidate() }); const status = trpc.learning.flashcards.updateStatus.useMutation(); const [index, setIndex] = useState(0); const [flipped, setFlipped] = useState(false); const [statusNotice, setStatusNotice] = useState(""); const card = data?.[index];
  const makeCards = (event: React.FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = new FormData(event.currentTarget); generate.mutate({ topic: String(form.get("topic")), source: String(form.get("source") || "") }); };
  const advance = (direction: number) => { setIndex((current) => Math.max(0, Math.min((data?.length || 1) - 1, current + direction))); setFlipped(false); };
  const saveStatus = (nextStatus: "known" | "review") => { if (!card || status.isPending) return; status.mutate({ id: card.id, status: nextStatus }, { onSuccess: () => { setStatusNotice(nextStatus === "known" ? "Saved: you know this card." : "Saved: this card is in review."); utils.learning.flashcards.list.invalidate(); advance(1); }, onError: () => setStatusNotice("The card status could not be saved. Please try again.") }); };
  return <div className="grid gap-6 xl:grid-cols-[.65fr_1.35fr]"><form onSubmit={makeCards} className="nova-form-card h-fit space-y-4"><strong>Generate a revision set</strong><Input required name="topic" placeholder="Topic" className="nova-input" /><Textarea name="source" placeholder="Optional: paste a note or key points" className="nova-input min-h-36" /><button className="nova-button w-full" disabled={generate.isPending}>{generate.isPending ? <Loader2 className="animate-spin" size={16} /> : <WandSparkles size={16} />} Create flashcards</button><p className="text-xs leading-5 text-muted-foreground">Your generated cards stay in your private learning workspace.</p></form><Panel title={data?.length ? `${index + 1} of ${data.length} cards` : "Your revision deck"}>{card ? <div className="flex min-h-[430px] flex-col"><div className="mb-3 flex items-center justify-between text-xs text-muted-foreground"><span>Current status: <strong className="text-foreground capitalize">{card.status}</strong></span>{statusNotice && <span className="text-amber-500">{statusNotice}</span>}</div><button onClick={() => setFlipped(!flipped)} className={`nova-flashcard ${flipped ? "is-flipped" : ""}`}><span className="nova-card-label">{flipped ? "Answer" : "Prompt"}</span><p>{flipped ? card.answer : card.question}</p><small>Tap to flip</small></button><div className="mt-5 flex flex-wrap items-center justify-between gap-3"><div className="flex gap-2"><button className="nova-icon-button" onClick={() => advance(-1)} disabled={index === 0}><ChevronLeft size={18} /></button><button className="nova-icon-button" onClick={() => advance(1)} disabled={index === (data?.length || 1) - 1}><ChevronRight size={18} /></button></div><div className="flex gap-2"><button className="nova-button-secondary" disabled={status.isPending} onClick={() => saveStatus("review")}>{status.isPending ? <Loader2 className="animate-spin" size={15} /> : <RotateCcw size={15} />} Review again</button><button className="nova-button" disabled={status.isPending} onClick={() => saveStatus("known")}>{status.isPending ? <Loader2 className="animate-spin" size={15} /> : <Check size={15} />} I know this</button></div></div></div> : <Empty text="Generate cards from a topic or a note, then use the review controls to build momentum." icon={Layers3} />}</Panel></div>;
}

function SummarizePage() {
  const [source, setSource] = useState(""); const [length, setLength] = useState<"short" | "medium" | "detailed">("medium"); const [output, setOutput] = useState(""); const utils = trpc.useUtils(); const summarize = trpc.learning.summarize.useMutation({ onSuccess: (data) => setOutput(data.summary) }); const save = trpc.productivity.notes.create.useMutation({ onSuccess: () => utils.productivity.notes.list.invalidate() });
  const download = () => { const blob = new Blob([output], { type: "text/markdown" }); const url = URL.createObjectURL(blob); const link = document.createElement("a"); link.href = url; link.download = "learnova-summary.md"; link.click(); URL.revokeObjectURL(url); };
  return <div className="grid gap-6 xl:grid-cols-2"><div className="nova-form-card space-y-4"><div><strong>Source material</strong><p className="mt-1 text-sm text-muted-foreground">Paste text from a lecture, a reading, or your own notes.</p></div><Textarea value={source} onChange={(event) => setSource(event.target.value)} placeholder="Paste study material here…" className="nova-input min-h-[330px]" /><div className="flex flex-wrap items-center justify-between gap-3"><div className="nova-filter-tabs">{(["short", "medium", "detailed"] as const).map((item) => <button key={item} className={length === item ? "is-active" : ""} onClick={() => setLength(item)}>{item}</button>)}</div><button onClick={() => summarize.mutate({ source, length })} disabled={!source.trim() || summarize.isPending} className="nova-button">{summarize.isPending ? <Loader2 className="animate-spin" size={16} /> : <WandSparkles size={16} />} Summarize</button></div></div><Panel title="Your study summary">{output ? <div className="space-y-5"><div className="nova-summary-output whitespace-pre-wrap">{output}</div><div className="flex flex-wrap gap-2"><button onClick={() => navigator.clipboard.writeText(output)} className="nova-button-secondary"><Copy size={15} /> Copy</button><button onClick={download} className="nova-button-secondary"><Download size={15} /> Download</button><button onClick={() => save.mutate({ title: "AI study summary", subject: "General", content: output, tags: "summary, ai" })} className="nova-button"><Archive size={15} /> Save as note</button></div></div> : <Empty text="Your summary will include the key idea, revision points, terms, and useful questions." icon={BookOpenText} />}</Panel></div>;
}

function CalendarPage() {
  const utils = trpc.useUtils(); const { data, isLoading } = trpc.productivity.calendar.list.useQuery(); const create = trpc.productivity.calendar.create.useMutation({ onSuccess: () => utils.productivity.calendar.list.invalidate() }); const remove = trpc.productivity.calendar.remove.useMutation({ onSuccess: () => utils.productivity.calendar.list.invalidate() }); const [showForm, setShowForm] = useState(false);
  const submit = (event: React.FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = new FormData(event.currentTarget); create.mutate({ title: String(form.get("title")), category: String(form.get("category")) as "task" | "study" | "exam" | "deadline" | "other", startsAt: new Date(String(form.get("startsAt"))), durationMinutes: Number(form.get("duration")), notes: String(form.get("notes") || "") }); setShowForm(false); };
  const groups = useMemo(() => (data || []).reduce<Record<string, typeof data>>((all, event) => { const key = new Date(event.startsAt).toDateString(); (all[key] ||= []).push(event); return all; }, {}), [data]);
  return <div className="space-y-6"><div className="flex justify-between"><p className="text-sm text-muted-foreground">Add study sessions to bring live study-time data into your analytics.</p><button onClick={() => setShowForm(!showForm)} className="nova-button"><Plus size={16} /> Add event</button></div>{showForm && <form onSubmit={submit} className="nova-form-card grid gap-4 md:grid-cols-2"><Input required name="title" placeholder="Event title" className="nova-input" /><select name="category" className="nova-input"><option value="study">Study session</option><option value="deadline">Deadline</option><option value="exam">Exam</option><option value="task">Task</option><option value="other">Other</option></select><Input required name="startsAt" type="datetime-local" className="nova-input" /><Input required name="duration" type="number" min="15" max="720" defaultValue="60" className="nova-input" /><Textarea name="notes" placeholder="Optional notes" className="nova-input md:col-span-2" /><div className="flex justify-end md:col-span-2"><button className="nova-button"><CalendarDays size={16} /> Save event</button></div></form>}<Panel title="Schedule" action={`${data?.length || 0} events`}>{isLoading ? <LoadingRows /> : Object.keys(groups).length ? <div className="space-y-7">{Object.entries(groups).map(([date, events]) => <div key={date}><p className="mb-3 text-xs font-semibold uppercase tracking-[.13em] text-muted-foreground">{date}</p><div className="space-y-2">{events?.map((event) => <div key={event.id} className="nova-calendar-row"><span className={`nova-event-dot nova-event-${event.category}`} /><div className="min-w-0 flex-1"><p>{event.title}</p><small>{new Date(event.startsAt).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })} · {event.durationMinutes} min · {event.category}</small></div><button onClick={() => { if (confirm("Remove this event?")) remove.mutate({ id: event.id }); }} className="nova-icon-button hover:text-rose-400"><Trash2 size={15} /></button></div>)}</div></div>)}</div> : <Empty text="Add a deadline, exam, or study session to give your week a visible structure." icon={CalendarDays} />}</Panel></div>;
}

function AnalyticsPage() {
  const { data, isLoading } = trpc.dashboard.analytics.useQuery(); const metricCards = [["Task completion", `${data?.taskCompletion || 0}%`, CheckCircle2, "cyan"], ["Quiz average", `${data?.quizAverage || 0}%`, BrainCircuit, "violet"], ["Study streak", `${data?.streak || 0} days`, Sparkles, "rose"], ["Scheduled study", `${Math.round((data?.scheduledStudyMinutes || 0) / 60 * 10) / 10}h`, Clock3, "blue"]] as const;
  if (isLoading) return <LoadingCards />;
  return <div className="space-y-6"><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{metricCards.map(([label, value, Icon, color]) => <article className="nova-stat-card" key={label}><span className={`nova-stat-icon nova-stat-${color}`}><Icon size={19} /></span><div><p>{label}</p><strong>{value}</strong><small>Current view</small></div></article>)}</div><div className="grid gap-6 xl:grid-cols-[1.2fr_.8fr]"><Panel title="Study time trend"><div className="h-[310px]">{data?.trend?.some((item) => item.minutes) ? <ResponsiveContainer width="100%" height="100%"><AreaChart data={data.trend}><defs><linearGradient id="analyticsGradient" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stopColor="#ef7d31" stopOpacity={.42} /><stop offset="100%" stopColor="#ef7d31" stopOpacity={0} /></linearGradient></defs><XAxis dataKey="label" axisLine={false} tickLine={false} tick={{ fill: "#9a7357", fontSize: 11 }} /><YAxis axisLine={false} tickLine={false} tick={{ fill: "#9a7357", fontSize: 11 }} /><Tooltip contentStyle={{ borderRadius: 16, background: "#fff8ec", border: "1px solid rgba(255,255,255,.1)" }} /><Area type="monotone" dataKey="minutes" stroke="#a78bfa" strokeWidth={2.5} fill="url(#analyticsGradient)" /></AreaChart></ResponsiveContainer> : <Empty text="Add a study session in Calendar to start building this chart." icon={BarChart3} />}</div></Panel><Panel title="Subject focus"><div className="h-[310px]">{data?.subjects?.length ? <ResponsiveContainer width="100%" height="100%"><BarChart data={data.subjects} layout="vertical"><XAxis type="number" hide /><YAxis dataKey="name" type="category" width={80} axisLine={false} tickLine={false} tick={{ fill: "#9a7357", fontSize: 12 }} /><Tooltip contentStyle={{ borderRadius: 16, background: "#fff8ec", border: "1px solid rgba(255,255,255,.1)" }} /><Bar dataKey="minutes" fill="#e86d2d" radius={[0, 8, 8, 0]} /></BarChart></ResponsiveContainer> : <Empty text="Log a study session with a subject to compare your focus areas." icon={BookOpenText} />}</div></Panel></div><Panel title="AI insight"><div className="nova-recommendation"><Lightbulb size={19} /><p>{data?.streak ? `You have built a ${data.streak}-day learning streak. Protect it with one purposeful study block today.` : "Your analytics are ready to start learning from your study sessions, tasks, and quiz results."}</p></div></Panel></div>;
}

function SettingsPage() {
  const { data, isLoading } = trpc.productivity.settings.get.useQuery(); const update = trpc.productivity.settings.update.useMutation(); const { user } = useAuth();
  if (isLoading) return <LoadingCards />;
  return <div className="grid gap-6 xl:grid-cols-[.8fr_1.2fr]"><Panel title="Profile"><div className="flex items-center gap-4"><span className="grid h-14 w-14 place-items-center rounded-2xl bg-gradient-to-br from-amber-300 to-orange-500 text-lg font-bold text-white">{(user?.name || "N").slice(0, 1).toUpperCase()}</span><div><p className="font-medium">{user?.name || "Learnova learner"}</p><small>{user?.email || "Secure personal workspace"}</small></div></div><p className="mt-5 text-sm leading-6 text-muted-foreground">Your identity is managed through secure sign-in. Learning data remains scoped to your personal workspace.</p></Panel><div className="space-y-6"><Panel title="Learning preferences"><div className="grid gap-4 sm:grid-cols-2"><SettingSelect label="AI response style" value={data?.aiResponseStyle || "balanced"} options={["concise", "balanced", "detailed"]} onChange={(value) => update.mutate({ aiResponseStyle: value as "concise" | "balanced" | "detailed" })} /><SettingSelect label="Preferred difficulty" value={data?.preferredDifficulty || "medium"} options={["easy", "medium", "hard"]} onChange={(value) => update.mutate({ preferredDifficulty: value as "easy" | "medium" | "hard" })} /></div></Panel><Panel title="Reminders"><div className="grid gap-4 sm:grid-cols-2"><SettingSelect label="Study reminders" value={data?.notificationsEnabled || "yes"} options={["yes", "no"]} onChange={(value) => update.mutate({ notificationsEnabled: value as "yes" | "no" })} /><label className="block text-sm font-medium">Reminder time<Input type="time" defaultValue={data?.reminderTime || "18:00"} onBlur={(event) => update.mutate({ reminderTime: event.target.value })} className="nova-input mt-2" /></label></div></Panel><Panel title="Privacy"><p className="text-sm leading-6 text-muted-foreground">Learnova applies authenticated, user-specific access controls across saved tasks, notes, documents, plans, conversations, quizzes, cards, events, and settings.</p></Panel></div></div>;
}

function Panel({ title, action, onAction, children }: { title: string; action?: string; onAction?: () => void; children: React.ReactNode }) { return <section className="nova-panel"><div className="mb-5 flex items-center justify-between"><h2>{title}</h2>{action && <button onClick={onAction} className="text-xs font-medium text-orange-600 transition hover:text-cyan-100">{action}</button>}</div>{children}</section>; }
function Empty({ text, icon: Icon }: { text: string; icon: React.ComponentType<{ size?: number }> }) { return <div className="nova-empty"><span><Icon size={21} /></span><p>{text}</p></div>; }
function LoadingCards({ count = 4 }: { count?: number }) { return <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{Array.from({ length: count }, (_, index) => <div className="nova-skeleton h-32" key={index} />)}</div>; }
function LoadingRows() { return <div className="space-y-3">{Array.from({ length: 4 }, (_, index) => <div className="nova-skeleton h-16" key={index} />)}</div>; }
function SettingSelect({ label, value, options, onChange }: { label: string; value: string; options: string[]; onChange: (value: string) => void }) { return <label className="block text-sm font-medium">{label}<select value={value} onChange={(event) => onChange(event.target.value)} className="nova-input mt-2">{options.map((option) => <option key={option} value={option}>{option}</option>)}</select></label>; }
function formatDate(value: Date | string | null) { return value ? new Date(value).toLocaleDateString([], { month: "short", day: "numeric" }) : ""; }
function dateInput(value: Date | string) { const date = new Date(value); return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`; }
const GraduationCapIcon = BrainCircuit; const CheckSquareIcon = CheckCircle2; const NotebookIcon = NotebookPen;

function NotesWorkspace() {
  const { data: noteData } = trpc.productivity.notes.list.useQuery({ query: "" });
  const [noteId, setNoteId] = useState<number | null>(null); const [output, setOutput] = useState("");
  const summary = trpc.learning.summarize.useMutation({ onSuccess: (data) => setOutput(data.summary) });
  const flashcards = trpc.learning.flashcards.generate.useMutation({ onSuccess: (data) => setOutput(`Created ${data.cards.length} flashcards. Open Flashcards to begin your revision.`) });
  const chat = trpc.learning.chat.send.useMutation({ onSuccess: (data) => setOutput(data.response) });
  const selected = noteData?.find((note) => note.id === noteId) || noteData?.[0];
  const runAction = (action: "summary" | "questions" | "flashcards" | "simple") => {
    if (!selected) return;
    setNoteId(selected.id);
    if (action === "summary") summary.mutate({ source: selected.content, length: "medium" });
    if (action === "flashcards") flashcards.mutate({ topic: selected.subject || selected.title, source: selected.content });
    if (action === "questions") chat.mutate({ conversationId: "primary", message: `Generate five targeted revision questions from this note titled “${selected.title}”.\n\n${selected.content}` });
    if (action === "simple") chat.mutate({ conversationId: "primary", message: `Explain this note simply, using a concise analogy where helpful.\n\n${selected.content}` });
  };
  return <div className="space-y-6"><NotesPage /><Panel title="Learnova note actions"><div className="grid gap-4 lg:grid-cols-[.55fr_.45fr]"><div><select value={selected?.id || ""} onChange={(event) => setNoteId(Number(event.target.value))} className="nova-input w-full">{noteData?.length ? noteData.map((note) => <option key={note.id} value={note.id}>{note.title}</option>) : <option value="">Create a note to unlock AI actions</option>}</select><div className="mt-3 grid grid-cols-2 gap-2">{[["summary", "Summarize", BookOpenText], ["questions", "Questions", MessageSquareText], ["flashcards", "Flashcards", Layers3], ["simple", "Explain simply", Lightbulb]].map(([key, label, Icon]) => <button disabled={!selected || summary.isPending || chat.isPending || flashcards.isPending} key={key as string} onClick={() => runAction(key as "summary" | "questions" | "flashcards" | "simple")} className="nova-quick-action"><Icon size={15} /><span>{label as string}</span></button>)}</div></div><div className="nova-ai-output">{summary.isPending || chat.isPending || flashcards.isPending ? <p><Loader2 className="inline animate-spin" size={15} /> Learnova is working with this note…</p> : output ? <div className="prose prose-sm max-w-none whitespace-pre-wrap dark:prose-invert"><Streamdown>{output}</Streamdown></div> : <p>Choose a note, then turn it into a summary, questions, flashcards, or a simpler explanation.</p>}</div></div></Panel></div>;
}

function AssistantWorkspace() {
  const utils = trpc.useUtils(); const inputRef = useRef<HTMLInputElement>(null); const [attachment, setAttachment] = useState<{ name: string; text: string } | null>(null); const [requestError, setRequestError] = useState("");
  const { data, isLoading } = trpc.learning.chat.list.useQuery({ conversationId: "primary" }); const send = trpc.learning.chat.send.useMutation({ onSuccess: () => utils.learning.chat.list.invalidate() }); const clear = trpc.learning.chat.clear.useMutation({ onSuccess: () => utils.learning.chat.list.invalidate() });
  const upload = trpc.learning.documents.upload.useMutation({ onSuccess: (result, variables) => { setAttachment({ name: variables.filename, text: result.extractedText }); setRequestError(""); }, onError: (error) => setRequestError(error.message || "The document could not be read. Use a readable PDF, DOCX, or TXT file under 5 MB.") }); const messages: Message[] = (data || []).map((message) => ({ role: message.role, content: message.message }));
  const attach = (event: ChangeEvent<HTMLInputElement>) => { const file = event.target.files?.[0]; if (!file) return; setRequestError(""); const reader = new FileReader(); reader.onerror = () => setRequestError("The selected file could not be read from your computer."); reader.onload = () => upload.mutate({ filename: file.name, mimeType: file.type, base64: String(reader.result).split(",")[1] || "" }); reader.readAsDataURL(file); };
  const sendMessage = async (message: string) => { setRequestError(""); try { await send.mutateAsync({ message, attachmentText: attachment?.text, conversationId: "primary" }); } catch (error) { const text = error instanceof Error ? error.message : "Learnova could not answer this question."; setRequestError(text); throw new Error(text); } };
  return <div className="grid gap-6 xl:grid-cols-[.28fr_.72fr]"><Panel title="Prompt library"><div className="space-y-2">{["Explain DBMS normalization simply.", "Create a three-day DBMS study plan.", "Quiz me on Python functions.", "Turn OS scheduling into flashcards."].map((prompt) => <button key={prompt} onClick={() => void sendMessage(prompt)} className="nova-prompt"><Sparkles size={15} />{prompt}</button>)}</div><div className="mt-6 border-t border-border pt-5"><p className="text-xs leading-5 text-muted-foreground">Attach a readable PDF, DOCX, or TXT file, then ask a specific question. Your material stays attached until you remove it.</p><button onClick={() => { if (confirm("Clear this private conversation?")) clear.mutate({ conversationId: "primary" }); }} className="mt-4 flex items-center gap-2 text-sm text-muted-foreground hover:text-rose-400"><Trash2 size={15} /> Clear chat</button></div></Panel><div className="nova-chat-shell"><div className="nova-chat-top"><span className="nova-mark h-8 w-8"><Sparkles size={14} /></span><div><p className="text-sm font-medium">Learnova study coach</p><p className="text-xs text-orange-600">{attachment ? `${attachment.name} attached — ask your question below` : "Ready for your next question"}</p></div><label className="ml-auto nova-attach"><Upload size={15} /> <span>{upload.isPending ? "Reading…" : "Attach context"}</span><input ref={inputRef} type="file" accept=".pdf,.docx,.txt,application/pdf,text/plain,application/vnd.openxmlformats-officedocument.wordprocessingml.document" onChange={attach} /></label>{attachment && <button title="Remove attached material" onClick={() => setAttachment(null)} className="nova-icon-button"><X size={15} /></button>}</div>{requestError && <p role="alert" className="mx-4 mt-3 rounded-xl border border-rose-200 bg-rose-50 px-3 py-2 text-xs font-medium text-rose-700">{requestError}</p>}<AIChatBox messages={messages} onSendMessage={sendMessage} isLoading={isLoading || send.isPending || upload.isPending} height="570px" className="border-0 bg-transparent shadow-none" emptyStateMessage="Start with a topic, a confusing concept, or a study goal." suggestedPrompts={["Explain this simply", "Create a study plan", "Quiz me on this topic"]} /></div></div>;
}

function PlannerWorkspace() {
  const utils = trpc.useUtils(); const { data } = trpc.learning.planner.list.useQuery(); const update = trpc.learning.planner.update.useMutation({ onSuccess: () => utils.learning.planner.list.invalidate() }); const regenerate = trpc.learning.planner.regenerate.useMutation({ onSuccess: () => utils.learning.planner.list.invalidate() });
  const refine = (plan: any) => { const current = (plan.planData as StudyDay[]).map((day) => `${day.day} | ${day.focus} | ${day.duration}`).join("\n"); const draft = prompt("Edit every study day using: Day number | Focus | Duration", current); if (!draft) return; const days = draft.split("\n").map((line, index) => { const [dayText, focus, duration] = line.split("|").map((part) => part.trim()); const existing = (plan.planData as StudyDay[])[index]; return { day: Number(dayText) || index + 1, focus: focus || existing?.focus || "Focused review", duration: duration || existing?.duration || "60 min", complete: existing?.complete || false }; }).filter((day) => day.focus); update.mutate({ id: plan.id, planData: days, progress: Math.round((days.filter((day) => day.complete).length / Math.max(days.length, 1)) * 100) }); };
  return <div className="space-y-6"><PlannerPage />{data?.length ? <Panel title="Plan refinement"><div className="space-y-2">{data.map((plan) => <div key={plan.id} className="nova-list-row"><span className="nova-stat-icon nova-stat-violet"><ClipboardList size={15} /></span><div className="min-w-0 flex-1"><p>{plan.subject}</p><small>Adjust the first focus or rebuild this plan from its saved details.</small></div><button className="nova-button-secondary" onClick={() => refine(plan)}><PenLine size={14} /> Edit</button><button className="nova-button" onClick={() => regenerate.mutate({ id: plan.id })}><RotateCcw size={14} /> Regenerate</button></div>)}</div></Panel> : null}</div>;
}

function FlashcardsWorkspace() {
  const { data } = trpc.learning.flashcards.list.useQuery({}); const total = data?.length || 0; const known = data?.filter((card) => card.status === "known").length || 0; const review = data?.filter((card) => card.status === "review").length || 0;
  return <div className="space-y-6"><div className="grid gap-3 sm:grid-cols-3">{[["Known", known, "cyan"], ["Review again", review, "violet"], ["Revision progress", total ? `${Math.round((known / total) * 100)}%` : "0%", "blue"]].map(([label, value, color]) => <div className="nova-revision-metric" key={label as string}><span className={`nova-event-dot nova-event-${color === "cyan" ? "study" : color === "violet" ? "task" : "other"}`} /><p>{label as string}</p><strong>{value as string | number}</strong></div>)}</div><FlashcardsPage /></div>;
}

function CalendarWorkspace() {
  const { data: events } = trpc.productivity.calendar.list.useQuery(); const { data: tasks } = trpc.productivity.tasks.list.useQuery({ filter: "all" }); const [offset, setOffset] = useState(0);
  const days = useMemo(() => { const start = new Date(); start.setDate(start.getDate() - start.getDay() + offset * 7); start.setHours(0, 0, 0, 0); return Array.from({ length: 7 }, (_, index) => { const day = new Date(start); day.setDate(start.getDate() + index); return day; }); }, [offset]);
  const itemsForDay = (day: Date) => [...(events || []).filter((event) => new Date(event.startsAt).toDateString() === day.toDateString()).map((event) => ({ id: `e${event.id}`, title: event.title, category: event.category })), ...(tasks || []).filter((task) => task.deadline && new Date(task.deadline).toDateString() === day.toDateString()).map((task) => ({ id: `t${task.id}`, title: task.title, category: "task" }))];
  return <div className="space-y-6"><Panel title="Week at a glance" action="Today" onAction={() => setOffset(0)}><div className="mb-4 flex justify-between"><button className="nova-icon-button" onClick={() => setOffset(offset - 1)}><ChevronLeft size={17} /></button><p className="text-sm font-medium">{days[0]?.toLocaleDateString([], { month: "short", day: "numeric" })} – {days[6]?.toLocaleDateString([], { month: "short", day: "numeric" })}</p><button className="nova-icon-button" onClick={() => setOffset(offset + 1)}><ChevronRight size={17} /></button></div><div className="nova-week-grid">{days.map((day) => <div key={day.toISOString()} className={`nova-week-day ${day.toDateString() === new Date().toDateString() ? "is-today" : ""}`}><p><span>{day.toLocaleDateString([], { weekday: "short" })}</span><strong>{day.getDate()}</strong></p><div>{itemsForDay(day).map((item) => <span className={`nova-week-event nova-event-${item.category}`} key={item.id}>{item.title}</span>)}</div></div>)}</div></Panel><CalendarPage /></div>;
}

function SettingsWorkspace() {
  const utils = trpc.useUtils(); const { data: profile } = trpc.productivity.profile.get.useQuery(); const updateName = trpc.productivity.profile.updateName.useMutation({ onSuccess: () => utils.productivity.profile.get.invalidate() }); const upload = trpc.productivity.profile.uploadAvatar.useMutation({ onSuccess: () => utils.productivity.profile.get.invalidate() }); const fileRef = useRef<HTMLInputElement>(null); const [name, setName] = useState(""); const [avatarError, setAvatarError] = useState("");
  const attachAvatar = (event: ChangeEvent<HTMLInputElement>) => { const file = event.target.files?.[0]; if (!file) return; if (!['image/jpeg', 'image/png', 'image/webp'].includes(file.type) || file.size > 2 * 1024 * 1024) { setAvatarError("Choose a JPG, PNG, or WEBP image smaller than 2 MB."); return; } setAvatarError(""); const reader = new FileReader(); reader.onerror = () => setAvatarError("The selected image could not be read."); reader.onload = () => upload.mutate({ filename: file.name, mimeType: file.type as "image/jpeg" | "image/png" | "image/webp", base64: String(reader.result).split(",")[1] || "" }, { onError: (error) => setAvatarError(error.message || "The profile photo could not be saved.") }); reader.readAsDataURL(file); };
  return <div className="space-y-6"><Panel title="Profile and avatar"><div className="grid gap-5 sm:grid-cols-[auto_1fr]"><button title="Choose a profile photo" aria-label="Choose a profile photo" onClick={() => fileRef.current?.click()} className="relative grid h-20 w-20 place-items-center overflow-hidden rounded-2xl bg-gradient-to-br from-amber-300 to-orange-500 text-xl font-bold text-white">{profile?.avatarUrl ? <img src={profile.avatarUrl} alt="Profile avatar" className="h-full w-full object-cover" /> : (profile?.name || "N").slice(0, 1).toUpperCase()}<input ref={fileRef} type="file" accept="image/jpeg,image/png,image/webp" onChange={attachAvatar} className="hidden" /></button><div><p className="text-sm font-medium">Identity in your workspace</p><div className="mt-3 flex flex-wrap gap-2"><button type="button" onClick={() => fileRef.current?.click()} className="nova-button-secondary"><Upload size={15} /> {upload.isPending ? "Uploading…" : "Upload profile photo"}</button><Input value={name} onChange={(event) => setName(event.target.value)} placeholder={profile?.name || "Your display name"} className="nova-input max-w-xs" /><button disabled={!name.trim() || updateName.isPending} onClick={() => updateName.mutate({ name })} className="nova-button">Save name</button></div><p className="mt-2 text-xs text-muted-foreground">Choose a JPG, PNG, or WEBP image up to 2 MB. Your image is stored only in your protected workspace.</p>{avatarError && <p role="alert" className="mt-2 text-xs font-medium text-rose-600">{avatarError}</p>}</div></div></Panel><SettingsPage /></div>;
}
